import './style.css';
import {createIcons,Compass,BriefcaseBusiness,Building2,CalendarDays,GraduationCap,Gift,Star,Wrench,Users,Bookmark,ArrowUpRight,ArrowRight,Search,MapPin,Clock,Bell,Menu,X,Sparkles,Rocket,FileText,Mic,ChevronRight,ShieldCheck,LayoutDashboard,LogOut,Check,Plus,Trash2,Download,BookOpen,Play,Heart} from 'lucide';
const icons={Compass,BriefcaseBusiness,Building2,CalendarDays,GraduationCap,Gift,Star,Wrench,Users,Bookmark,ArrowUpRight,ArrowRight,Search,MapPin,Clock,Bell,Menu,X,Sparkles,Rocket,FileText,Mic,ChevronRight,ShieldCheck,LayoutDashboard,LogOut,Check,Plus,Trash2,Download,BookOpen,Play,Heart};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),ico=n=>`<i class="icon" data-lucide="${n}"></i>`;
const state={session:{user:null},items:[],me:null,filter:'Hamısı',search:'',manage:null,pusula:null,afterLogin:null};let routeToken=0,timerInterval=null,timerSeconds=25*60,timerEnd=0;
const nav=[['home','Kəşf et','compass'],['opportunities','İmkanlar','briefcase-business'],['companies','Şirkətlər','building-2'],['events','Tədbirlər','calendar-days'],['academy','Akademiya','graduation-cap'],['campus','Kampus və icmalar','users'],['reviews','Maaşlar və rəylər','star'],['tools','İnkişaf alətləri','wrench'],['privileges','Üstünlüklər','gift']];
const azDate=d=>{const x=new Date(d);return x.getDate()+' '+['yanvar','fevral','mart','aprel','may','iyun','iyul','avqust','sentyabr','oktyabr','noyabr','dekabr'][x.getMonth()]+' '+x.getFullYear()};
const statuses={submitted:'Göndərildi',reviewing:'Baxılır',interview:'Müsahibə',accepted:'Qəbul edildi',rejected:'Qəbul edilmədi',withdrawn:'Geri götürüldü',registered:'Qeydiyyat aktivdir',cancelled:'Ləğv edildi',pending:'Təsdiq gözləyir',published:'Yayımlanıb',archived:'Arxivdə',offer:'Təklif',draft:'Qaralama',closed:'Bağlanıb'};
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(state.session.csrf?{'X-CSRF-Token':state.session.csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});let d;try{d=await r.json()}catch{throw new Error('Serverlə əlaqə alınmadı. Yenidən yoxla.')}if(!r.ok)throw Object.assign(new Error(d.error||'Əməliyyat alınmadı.'),{status:r.status});return d}
function refreshIcons(){createIcons({icons,attrs:{'aria-hidden':'true'}})}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function modal(title,html){$('#modal').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="iconbtn" data-action="close" aria-label="Bağla">${ico('x')}</button></div><div class="modal-body">${html}</div>`;if(!$('#modal').open)$('#modal').showModal();refreshIcons()}
const btn=(text,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const field=(name,title,value='',type='text',required=false)=>`<label>${title}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="10" autocomplete="current-password"':''}></label>`;
const area=(name,title,value='',required=false)=>`<label class="wide">${title}<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`;
const empty=(title,desc)=>`<div class="empty"><h3>${title}</h3><p>${desc}</p></div>`;
const sample=i=>i.body.sample?'<span class="tag sample">Sınaq nümunəsi</span>':'';
const logo=(i,n=0)=>`<div class="org-logo ${['','green','orange','blue'][n%4]}">${esc(i?.title==='BURA Sınaq Studiyası'?'B.':i?.title?.slice(0,3)||'B.')}</div>`;
const org=i=>state.items.find(x=>x.id===i.organization_id);
const saved=id=>state.me?.saved.some(x=>x.item_id===id&&x.kind==='save');
function card(i,n=0){const b=i.body,o=org(i);return `<article class="card"><div class="card-top">${logo(o||i,n)}<button class="iconbtn ${saved(i.id)?'selected':''}" data-action="save" data-id="${i.id}" aria-label="${saved(i.id)?'Saxlananlardan çıxar':'İmkanı saxla'}" aria-pressed="${!!saved(i.id)}">${ico('bookmark')}</button></div><p class="orgname">${esc(o?.title||b.category||'BURA Akademiya')}</p><h3><a href="#/item/${i.id}">${esc(i.title)}</a></h3><div class="pillrow"><span class="tag">${esc(b.category||b.level||'İnkişaf')}</span>${sample(i)}${(m=>m?`<span class="tag green">${m.pct}% uyğun</span>`:'')(i.kind==='opportunity'&&jobMatch(b))}</div><div class="card-meta"><span>${ico('map-pin')}${esc(b.city||'Onlayn')}</span><span>${ico('clock')}${esc(b.format||b.duration||(b.date?new Date(b.date).toLocaleDateString('az-AZ'):'Sərbəst'))}</span></div><div class="card-bottom"><span>${b.deadline?'Son tarix: '+esc(b.deadline):b.capacity?b.capacity+' yer':'Öz tempində öyrən'}</span><a class="textlink" href="#/item/${i.id}" aria-label="${esc(i.title)} — ətraflı">Bax ${ico('arrow-up-right')}</a></div></article>`}
function organizationCard(i,n=0){return `<article class="card"><a href="#/item/${i.id}" class="org-row">${logo(i,n)}<div><h3>${esc(i.title)}</h3><p>${esc(i.body.sector||i.body.type)} · ${esc(i.body.city)}</p></div></a><div class="card-bottom">${i.body.sample?sample(i):'<span class="tag">Kataloq profili</span>'}<a class="textlink" href="#/item/${i.id}">Kəşf et ${ico('arrow-up-right')}</a></div></article>`}
const pusulaStore={get(){try{return JSON.parse(localStorage.getItem('bura_pusula')||'null')}catch{return null}},set(v){try{localStorage.setItem('bura_pusula',JSON.stringify(v))}catch{}}},pusulaDone=()=>!!pusulaStore.get()?.done;
async function openPusula(token){const host=document.createElement('div');$('#app').replaceChildren(host);const user=state.session.user;if(user&&!state.me)state.me=await api('/me');const {mountPusula}=await import('./pusula.js');if(token!==routeToken||!host.isConnected)return;const pr=user?.profile||{},c=state.me?.compass;
 state.pusula=mountPusula(host,{api,loggedIn:!!user,profile:user?{rol:c?.rol||pr.specialty,yer:c?.yer||pr.university,ek:c?.ek,skills:splitList(pr.skills),interests:c?.interests||[]}:null,
  onLogin:mode=>login(mode,{force:true,returnHash:'#/home'}),onExit:()=>{location.hash=user?'#/profile':'#/home'},
  onFinish:async(result,{save,login:hasAccount})=>{pusulaStore.set({done:true,result,save});if(!state.session.user){if(save)return login(hasAccount?'login':'register',{force:true,returnHash:'#/profile'});location.hash='#/home';return}try{if(save)await saveCompass()}catch(e){toast(e.message)}location.hash='#/profile'}})}
const splitList=x=>String(x||'').split(',').map(v=>v.trim()).filter(Boolean);
// Girişdən əvvəl tamamlanan səyahət: hesab açılan kimi profilə bağlanır.
async function saveCompass(){const st=pusulaStore.get();if(!state.session.user)return false;if(!st?.result||!st.save){if(!st?.done)pusulaStore.set({done:true});return false}pusulaStore.set({done:true});await api('/compass','POST',st.result);state.me=await api('/me');state.session.user=state.me.user;toast('Arzu Kompası profilinə bağlandı.');return true}
const onboardKey=()=>'bura_onboard:'+state.session.user?.id;
function onboardOnce(){try{if(localStorage.getItem(onboardKey()))return false;localStorage.setItem(onboardKey(),'1')}catch{return false}return true}
let companyModule=null;
async function loadCompany(){if(!companyModule){companyModule=await import('./company.js');companyModule.init({api,state,modal,toast,esc,ico,btn,field,area,header,empty,logo,azDate,refreshIcons,$,render})}return companyModule}
const lowAz=v=>String(v||'').trim().toLocaleLowerCase('az');
// Elan bacarıqları ↔ profil + Arzu Kompası bacarıqları (server/company.mjs matchScore ilə eyni qayda).
function jobMatch(b){const u=state.session.user;if(!u||!b?.skills?.length)return null;const have=[...splitList(u.profile?.skills),...(state.me?.compass?.skills||[])].map(lowAz),want=b.skills.map(lowAz),hit=want.map(s=>have.some(h=>h===s||(h.length>3&&s.length>3&&(h.includes(s)||s.includes(h)))));return {pct:Math.round(hit.filter(Boolean).length/want.length*100),missing:b.skills.filter((s,k)=>!hit[k])}}
function matchedJobs(){if(!state.me)return '';const rows=state.items.filter(i=>i.kind==='opportunity').map(i=>[i,jobMatch(i.body)]).filter(([,m])=>m&&m.pct>0).sort((a,b)=>b[1].pct-a[1].pct).slice(0,3);return rows.length?`<div class="section-head"><div><h2>Sənə uyğun elanlar</h2><p>Bacarıqların və Arzu Kompası nəticən əsasında.</p></div><a href="#/opportunities">Hamısı →</a></div><div class="grid">${rows.map(([i],n)=>card(i,n)).join('')}</div>`:''}
function companyQueueHTML(qd){if(!qd)return '';return `<div class="section-head"><h2>Şirkət təsdiqi</h2></div><div class="card stack">${qd.companies.map(c=>`<div class="row"><div><h3>${esc(c.title)}</h3><p class="subtle">${esc(c.legalName||'')} · VÖEN ${esc(c.voen)} · ${esc(c.body.sector||'')}</p><span class="tag">${statuses[c.status]||c.status}</span></div><div class="actions">${btn('Təsdiqlə','co-verify',`data-id="${c.id}" data-v="1"`,'light')}</div></div>`).join('')||'<p class="subtle">Təsdiq gözləyən şirkət yoxdur.</p>'}</div><div class="section-head"><h2>Profil sahibliyi müraciətləri</h2></div><div class="card stack">${qd.claims.map(c=>`<div class="row"><div><h3>${esc(c.title)} · ${esc(c.name)}</h3><p class="subtle">${esc(c.email)} · ${esc(c.claim.title||'')} · VÖEN ${esc(c.claim.voen||'—')}</p></div><div class="actions">${btn('Təsdiqlə','co-claim-decide',`data-id="${c.organization_id}" data-user="${c.user_id}" data-v="1"`,'light')}${btn('Rədd et','co-claim-decide',`data-id="${c.organization_id}" data-user="${c.user_id}" data-v="0"`,'white')}</div></div>`).join('')||'<p class="subtle">Gözləyən müraciət yoxdur.</p>'}</div>`}
function shell(route){const user=state.session.user;$('#app').innerHTML=`<header class="topbar"><a class="brand qigilcim-brand" href="#/home" aria-label="Qığılcım ana səhifə"><img src="/qigilcim-mark.svg" alt="" width="40" height="40"><span>Qığılcım</span></a><nav class="nav" aria-label="Əsas naviqasiya">${[['home','Kəşf et'],['companies','Şirkətlər'],['opportunities','İmkanlar'],['events','Tədbirlər'],['academy','Akademiya']].map(([r,t])=>`<a class="${route===r?'active':''}" href="#/${r}">${t}</a>`).join('')}</nav><div class="navend"><button class="iconbtn header-search" data-action="search" aria-label="Axtar">${ico('search')}</button>${user?`<button class="iconbtn" data-action="notifications" aria-label="Bildirişlər">${ico('bell')}</button><a href="#/profile" class="avatar" aria-label="Profilim">${esc(user.name.slice(0,1))}</a>`:btn('Qoşul '+ico('arrow-up-right'),'login')}<button class="iconbtn mobile-toggle" data-action="menu" aria-label="Menyu" aria-expanded="false">${ico('menu')}</button></div></header><nav class="mobile-nav" aria-label="Mobil menyu">${nav.map(([r,t,i])=>`<a class="side-link" href="#/${r}">${ico(i)}${t}</a>`).join('')}<a class="side-link" href="#/profile">${ico('users')}Profilim</a><a class="side-link" href="#/manage">${ico('layout-dashboard')}Təşkilat paneli</a><a class="side-link" href="#/company">${ico('briefcase-business')}İşəgötürən paneli</a></nav><div class="layout"><aside class="sidebar"><p class="eyebrow">Sənin dünyan</p>${nav.map(([r,t,i])=>`<a class="side-link ${route===r?'active':''}" href="#/${r}">${ico(i)}${t}${r==='tools'?'<span class="tag">YENİ</span>':''}</a>`).join('')}<p class="eyebrow">Şəxsi məkan</p><a class="side-link ${route==='profile'?'active':''}" href="#/profile">${ico('users')}Profilim</a><a class="side-link ${route==='saved'?'active':''}" href="#/saved">${ico('bookmark')}Saxladıqlarım</a><a class="side-link ${route==='manage'?'active':''}" href="#/manage">${ico('layout-dashboard')}Təşkilat paneli</a><a class="side-link ${route==='company'?'active':''}" href="#/company">${ico('briefcase-business')}İşəgötürən paneli</a><div class="side-promo">${ico('sparkles')}<h3>Özünə yatırım et.</h3><p>İnkişafına uyğun planı kəşf et.</p><a href="#/plans" class="textlink">Planlara bax ${ico('arrow-right')}</a></div><div class="side-footer"><a href="#/about">BURA haqqında</a> · <a href="#/privacy">Məxfilik</a><br>© ${new Date().getFullYear()} BURA<br>Azərbaycan üçün hazırlanıb.</div></aside><main id="main" class="content" tabindex="-1"></main></div>`}
function header(title,desc){return `<div class="page-header"><h1>${title}</h1><p>${desc}</p></div>`}
function searchForm(){return `<form class="searchbar" id="search-form">${ico('search')}<label class="sr-only" for="search">İmkan, şirkət və ya tədbir axtar</label><input id="search" name="q" placeholder="İmkan, şirkət və ya tədbir axtar…" value="${esc(state.search)}"><button class="btn" type="submit">Axtar</button></form>`}
function home(){const name=state.session.user?.name.split(' ')[0];return `<div class="intro"><div><h2>${name?`Salam, ${esc(name)} 👋`:'Sənin yeni başlanğıcın 👋'}</h2><p>Kəşf et, öyrən, öz yolunu yarat.</p></div><span class="date">${azDate(new Date())}</span></div><section class="hero"><div class="hero-copy"><span class="overline">${ico('sparkles')} GƏNCLİYİN YENİ MƏKANI</span><h1>Gələcəyin<br><span>burada başlayır.</span></h1><p>İlk təcrübədən böyük ideyalara. Özünü inkişaf etdirmək üçün ehtiyacın olan hər şey bir yerdə.</p><a class="btn" href="#/opportunities">İmkanları kəşf et ${ico('arrow-up-right')}</a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="art-pill">${ico('graduation-cap')}<div>Hər gün bir addım<small>Yeni bacarıq. Yeni sən.</small></div></div><div class="art-core">${ico('rocket')}</div><div class="spark">✦</div><div class="art-pill two">${ico('check')}<div>Potensialını kəşf et<small>Öz yolunu özün yarat.</small></div></div></div></section>${searchForm()}<div class="section-head"><div><h2>Sənin üçün imkanlar</h2><p>Kiçik bir addım, böyük bir başlanğıc.</p></div><a href="#/opportunities">Hamısına bax →</a></div><div class="chips">${['Hamısı','Təcrübə','Könüllülük','Freelance'].map(x=>`<a class="chip ${x==='Hamısı'?'active':''}" href="#/opportunities?type=${encodeURIComponent(x)}">${x}</a>`).join('')}</div><div class="grid">${state.items.filter(x=>x.kind==='opportunity').slice(0,3).map(card).join('')}</div><div class="banner">${ico('sparkles')}<div><h2>Təcrübən azdır? Başlamaq üçün kifayətdir.</h2><p>CV-ni hazırla, müsahibə məşqi et və özünə güvən.</p></div><a href="#/tools" class="btn lime">İndi başla ${ico('arrow-up-right')}</a></div><div class="section-head"><div><h2>Gələcəyinlə tanış ol</h2><p>Şirkətlər, universitetlər və yeni icmalar.</p></div><a href="#/companies">Kataloqa bax →</a></div><div class="grid">${state.items.filter(x=>x.kind==='organization'&&!x.body.sample).slice(0,6).map(organizationCard).join('')}</div><p class="tiny">Kataloq profilləri tərəfdaşlıq təsdiqi deyil. Sınaq elanları xüsusi işarələnib.</p>`}
function listing(route){const configs={opportunities:['İmkanını kəşf et.','Təcrübə, könüllülük, freelance və iş imkanları.','opportunity'],events:['Bir araya gələk.','Yeni insanlarla tanış ol, öyrən və icmanın bir hissəsi ol.','event'],academy:['Öyrəndikcə böyü.','Öz tempində öyrən. Bacarığını yoxla. İrəliləyişini hesabında saxla.','course'],companies:['Şirkətləri yaxından tanı.','Azərbaycan üzrə təşkilat kataloqu. Təşkilat nümayəndələri öz profillərini yarada bilər.','organization'],campus:['Kampusdan kənara.','Universitetlər, tələbə klubları və karyera mərkəzləri üçün ortaq məkan.','organization'],reviews:['Təcrübəni paylaş.','Şirkət rəyləri və maaş məlumatları. Rəylər yoxlamadan sonra müəllifin adı olmadan yayımlanır.','organization'],saved:['Saxladıqların.','Sonra baxmaq istədiyin imkanlar bir yerdə.',null],search:['Axtarış nəticələri.','BURA daxilində imkanları, təşkilatları və kursları tap.',null]};const [title,desc,kind]=configs[route];let rows=state.items.filter(i=>!kind||i.kind===kind);if(route==='companies')rows=rows.filter(i=>!['university','club','career-center','school'].includes(i.body.type));if(route==='campus')rows=rows.filter(i=>['university','club','career-center','school'].includes(i.body.type));if(route==='saved')rows=rows.filter(i=>saved(i.id));if(state.filter!=='Hamısı'&&route==='opportunities')rows=rows.filter(i=>i.body.category===state.filter);if(state.search)rows=rows.filter(i=>(i.title+' '+(org(i)?.title||'')+' '+JSON.stringify(i.body)).toLocaleLowerCase('az').includes(state.search.toLocaleLowerCase('az')));return header(title,desc)+searchForm()+(route==='opportunities'?`<div class="chips">${['Hamısı','Təcrübə','Tam ştat','Part-time','Gənc mütəxəssis','Könüllülük','Freelance'].map(x=>`<button class="chip ${state.filter===x?'active':''}" data-action="filter" data-filter="${x}">${x}</button>`).join('')}</div>`:'')+(route==='companies'?'<div class="notice">Şirkətsən? <a class="textlink" href="#/company">İşəgötürən panelindən profil yarat və elan ver →</a></div>':'')+(route==='campus'?'<div class="notice">Karyera mərkəzini və ya tələbə klubunu əlavə etmək istəyirsən? <a class="textlink" href="#/manage">Təşkilat panelindən profil yarat →</a></div>':'')+(rows.length?`<div class="grid">${rows.map((i,n)=>i.kind==='organization'?organizationCard(i,n):card(i,n)).join('')}</div>`:empty('Hələ nəticə yoxdur.','Başqa açar söz və ya kateqoriya yoxla.'))}
async function itemPage(id){const {item:i,reviews,registrations}=await api('/items/'+id),b=i.body;const p=state.me?.progress.find(x=>x.item_id===id);const done=JSON.parse(p?.completed||'[]'),app=state.me?.applications.find(x=>x.item_id===id),reg=state.me?.registrations.find(x=>x.item_id===id);return `<a class="textlink" href="#/${i.kind==='organization'?'companies':i.kind==='course'?'academy':i.kind==='event'?'events':'opportunities'}">← Geri</a><section class="card detail" style="margin-top:20px"><div class="card-top">${logo(org(i)||i)}${sample(i)}</div><p class="orgname">${esc(org(i)?.title||b.sector||'BURA Akademiya')}</p><h1>${esc(i.title)}</h1><div class="pillrow">${[b.category,b.city,b.format,b.level,b.salary,b.sizeRange&&b.sizeRange+' əməkdaş'].filter(Boolean).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><p>${esc(b.description)}</p>${b.requirements?'<h3>Nələr gözlənilir?</h3><p>'+esc(b.requirements)+'</p>':''}${b.sample?'<div class="notice warning">Bu, platformanı yoxlamaq üçün nümunədir. Real iş təklifi və ya keçiriləcək tədbir deyil.</div>':''}${i.kind==='opportunity'&&b.skills?.length?`<h3>Bacarıqlar</h3><div class="pillrow">${b.skills.map(s=>`<span class="tag green">${esc(s)}</span>`).join('')}</div>${(m=>m?`<div class="notice">Profilin və Arzu Kompası nəticənlə uyğunluq: <strong>${m.pct}%</strong>${m.missing.length?' · İnkişaf etdirə bilərsən: '+m.missing.map(esc).join(', '):''}</div>`:'')(jobMatch(b))}`:''}${i.kind==='opportunity'&&b.questions?.length?`<p class="subtle">Müraciətdə ${b.questions.length} qısa ön seçim sualı var.</p>`:''}${i.kind==='opportunity'?`<div class="notice">Son müraciət: ${esc(b.deadline)}</div><div class="actions">${app?`<span class="tag">${statuses[app.status]}</span><a class="btn light" href="#/profile">Müraciətimə bax</a>`:btn('Müraciət et','apply',`data-id="${id}"`)}${btn(saved(id)?'Saxlananlardan çıxar':'Saxla','save',`data-id="${id}"`,'white')}</div>`:''}${i.kind==='event'?`<div class="notice">${new Date(b.date).toLocaleString('az-AZ',{timeZone:'Asia/Baku'})} (Bakı vaxtı) · ${registrations}/${b.capacity} yer</div><div class="actions">${reg?.status==='registered'?`${btn('Biletim','ticket',`data-id="${id}"`)}${btn('Qeydiyyatı ləğv et','cancel-event',`data-id="${id}"`,'white')}`:btn('Qeydiyyatdan keç','register-event',`data-id="${id}"`)}</div>`:''}${i.kind==='organization'?`${b.verified?'<div class="notice"><strong>✓ Təsdiqlənmiş şirkət.</strong> VÖEN BURA tərəfindən yoxlanılıb.</div>':`<div class="notice">${b.unclaimed?'Bu profil təşkilatın nümayəndəsi tərəfindən təsdiqlənməyib. Tərəfdaşlıq elan edilmir. <a class="textlink" href="#/company">Bu şirkətdə işləyirsən? Sahiblik müraciəti göndər →</a>':'İcma profili'}</div>`}${b.website?`<p><a class="textlink" href="${esc(b.website)}" target="_blank" rel="noopener noreferrer">${esc(b.website.replace(/^https?:\/\//,''))} ${ico('arrow-up-right')}</a></p>`:''}<div class="actions">${btn(state.me?.saved.some(x=>x.item_id===id&&x.kind==='follow')?'İzləməni dayandır':'İzlə','follow',`data-id="${id}"`)}${btn('Rəy və maaş paylaş','review',`data-id="${id}"`,'white')}</div>`:''}${i.kind==='course'?`<div class="notice">${done.length}/${b.lessons.length} dərs tamamlanıb. ${!state.session.user?'İrəliləyişi saxlamaq üçün hesabına daxil ol.':''}</div><div class="progress"><i style="width:${done.length/b.lessons.length*100}%"></i></div>${b.lessons.map((l,n)=>`<details class="lesson" ${n===done.length?'open':''}><summary>${done.includes(n)?'✓':'0'+(n+1)} · ${esc(l.title)}</summary><p>${esc(l.text)}</p><form data-form="lesson" data-id="${id}" data-lesson="${n}"><h3>${esc(l.question)}</h3>${l.options.map((o,k)=>`<label class="choice"><input type="radio" name="answer" value="${k}" required>${esc(o)}</label>`).join('')}<button class="btn" type="submit">Cavabı yoxla</button><div class="form-message" role="status"></div></form></details>`).join('')}${p?.certificate_id?btn('Sertifikatı yüklə '+ico('download'),'certificate',`data-id="${id}"`):''}`:''}</section>${i.kind==='organization'?`<div class="section-head"><h2>İcmanın rəyləri</h2></div>${reviews.length?reviews.map(r=>{const x=JSON.parse(r.body);return `<article class="card" style="margin-bottom:12px"><span class="tag">Anonim · ${x.rating}/5</span><h3 style="margin-top:15px">${esc(x.role)}</h3><p>${esc(x.text)}</p>${x.salary?`<strong>${x.salary} ₼ / ay</strong><p class="tiny">İstifadəçi tərəfindən paylaşılıb · aylıq xalis maaş</p>`:''}</article>`}).join(''):empty('İlk təcrübəni sən paylaş.','Yalnız təsdiqlənən rəylər burada görünür.')}<div class="section-head"><h2>Təşkilatın imkanları</h2></div><div class="grid">${state.items.filter(x=>x.kind!=='organization'&&(x.organization_id===id||state.items.find(o=>o.id===x.organization_id)?.body.parentId===id)).map(card).join('')||'<p class="subtle">Hazırda yayımlanmış imkan yoxdur.</p>'}</div>`:''}`}
function profileStrength(u,c){const p=u.profile||{},checks=[['specialty','İxtisas'],['university','Universitet'],['city','Şəhər'],['skills','Bacarıqlar'],['bio','Özün haqqında'],['experience','Təcrübə']].map(([k,t])=>[!!String(p[k]||'').trim(),t]);checks.push([!!c,'Arzu Kompası']);return {pct:Math.round(checks.filter(x=>x[0]).length/checks.length*100),missing:checks.filter(x=>!x[0]).map(x=>x[1])}}
function meHero(u,c){const p=u.profile||{},st=profileStrength(u,c),skills=splitList(p.skills),quote=(c&&!c.sample&&c.statement)||p.bio,path=c?.paths?.[c.picked];
 return `<section class="me-hero"><div class="me-avatar" aria-hidden="true">${esc(u.name.slice(0,1))}</div><div class="me-id"><p class="me-eyebrow">Sənin profilin</p><h1>${esc(u.name)}</h1><p class="me-line">${esc([p.specialty,p.university,p.city].filter(Boolean).join(' · ')||'İxtisasını və universitetini əlavə et')}</p>${path?`<p class="me-path-line">${ico('compass')}<span>Yolun: <strong>${esc(path.name)}</strong> · ${path.fit}% uyğunluq</span></p>`:''}${quote?`<blockquote class="me-quote">${esc(quote)}</blockquote>`:''}${skills.length||c?.interests?.length?`<div class="pillrow">${skills.slice(0,12).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}${(c?.interests||[]).slice(0,6).map(x=>`<span class="tag me-like">${ico('heart')}${esc(x)}</span>`).join('')}</div>`:''}</div>
 <aside class="me-strength" aria-label="Profil gücü"><strong>${st.pct}%</strong><span>Profil gücü</span><div class="progress"><i style="width:${st.pct}%"></i></div>${st.missing.length?`<p class="subtle">Əskik: ${st.missing.map(esc).join(', ')}</p>${st.missing.includes('Arzu Kompası')?btn('Kompası aç '+ico('arrow-right'),'pusula'):btn('Tamamla','focus-profile','','light')}`:'<p class="subtle">Profilin tamdır. Kompası yeniləyərək inkişafını izlə.</p>'}</aside></section>`}
function compassSection(c){if(!c)return `<section class="card me-cta"><div class="course-cover">${ico('compass')}<span>↗</span></div><div><h2>Profilini Arzu Kompası ilə qur.</h2><p class="subtle">2 dəqiqə: bacarıq və maraqlarını seç, sənə uyğun peşə yollarını, kimlik cümləni və 4 həftəlik planını profilinə bağla.</p>${btn('Kompası aç '+ico('arrow-right'),'pusula')}</div></section>`;
 const path=c.paths[c.picked]||c.paths[0],plan=c.kit?.plan||[],done=plan.filter(x=>x.done).length,others=c.paths.filter(x=>x!==path);
 return `<div class="section-head"><div><h2>Arzu Kompası</h2><p>${c.updatedAt?'Son yenilənmə: '+azDate(c.updatedAt):''}</p></div>${btn(ico('sparkles')+' Kompası yenilə','pusula','','white')}</div>${c.sample?'<div class="notice warning">Bu nəticə AI qoşulmadan, nümunə məzmunla yaradılıb. AI aktiv olanda kompası yenilə.</div>':''}
 <div class="grid two me-compass"><article class="card"><p class="orgname">Seçdiyin yol</p><div class="me-fit-row"><h2>${esc(path.name)}</h2><span class="me-fit"><strong>${path.fit}%</strong> uyğunluq</span></div><div class="progress"><i style="width:${path.fit}%"></i></div>${path.summary?`<p class="subtle">${esc(path.summary)}</p>`:''}${path.why?`<p class="me-why">${esc(path.why)}</p>`:''}${path.match.length?`<h3>Səndə var</h3><div class="pillrow">${path.match.map(x=>`<span class="tag green">${esc(x)}</span>`).join('')}</div>`:''}${path.gaps.length?`<h3>Əlavə olunacaq</h3><div class="pillrow">${path.gaps.map(x=>`<span class="tag sample">+ ${esc(x)}</span>`).join('')}</div>`:''}${path.firstStep?`<div class="notice"><strong>Bu həftə:</strong> ${esc(path.firstStep)}</div>`:''}</article>
 <article class="card me-plan"><p class="orgname">4 həftəlik plan</p><h2><span data-plan-count>${done}/${plan.length}</span> addım</h2><div class="progress"><i data-plan-bar style="width:${plan.length?done/plan.length*100:0}%"></i></div><div class="stack">${plan.map((x,i)=>`<label class="choice me-step"><input type="checkbox" data-plan="${i}" ${x.done?'checked':''}><span><small>${esc(x.week)}</small>${esc(x.todo)}</span></label>`).join('')||'<p class="subtle">Plan yoxdur. Kompası yenilə.</p>'}</div></article></div>
 <div class="grid two">${c.kit?.headline?`<article class="card"><p class="orgname">LinkedIn başlığın</p><p class="me-big">${esc(c.kit.headline)}</p>${btn('Kopyala','copy',`data-copy="${esc(c.kit.headline)}"`,'white')}</article>`:''}${c.kit?.cover?`<article class="card"><p class="orgname">Motivasiya məktubunun girişi</p><p>${esc(c.kit.cover)}</p>${btn('Kopyala','copy',`data-copy="${esc(c.kit.cover)}"`,'white')}</article>`:''}</div>
 <div class="grid two" style="margin-top:16px">${others.length?`<article class="card"><p class="orgname">Digər yolların</p><div class="pillrow">${others.map(x=>`<span class="tag">${esc(x.name)} · ${x.fit}%</span>`).join('')}</div></article>`:''}${c.kit?.questions?.length?`<article class="card"><p class="orgname">Müsahibədə sən soruş</p><ul class="me-questions">${c.kit.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></article>`:''}</div>`}
function profile(){const u=state.session.user,p=u.profile||{},m=state.me;return meHero(u,m.compass)+compassSection(m.compass)+matchedJobs()+`<div class="section-head"><h2>Fəaliyyətim</h2></div><div class="stat-grid"><div class="stat"><strong>${m.applications.length}</strong><span>Müraciət</span></div><div class="stat"><strong>${m.registrations.filter(x=>x.status==='registered').length}</strong><span>Tədbir qeydiyyatı</span></div><div class="stat"><strong>${m.progress.filter(x=>x.certificate_id).length}</strong><span>Tamamlanan kurs</span></div><div class="stat"><strong>${m.saved.filter(x=>x.kind==='save').length}</strong><span>Saxlanan imkan</span></div></div><section class="card formbox" id="profile-form"><h2>Profil məlumatları</h2><p class="subtle">Müraciət etdiyin təşkilat bu məlumatları görə biləcək.</p><form data-form="profile"><div class="field-grid">${field('name','Ad və soyad',u.name,'text',true)}${field('city','Şəhər',p.city)}${field('university','Universitet / məktəb',p.university)}${field('specialty','İxtisas',p.specialty)}${field('phone','Telefon (istəyə bağlı)',p.phone,'tel')}${field('skills','Bacarıqlar',p.skills)}${area('bio','Özün haqqında',p.bio)}${area('experience','Təcrübə və layihələr',p.experience)}</div><button class="btn" type="submit">Dəyişiklikləri saxla</button><div class="form-message" role="status"></div></form></section><div class="section-head"><h2>Müraciətlərim</h2></div><div class="card">${m.applications.length?m.applications.map(a=>`<div class="row"><div><h3><a href="#/item/${a.item_id}">${esc(a.title)}</a></h3><span class="tag">${statuses[a.status]}</span></div>${a.status!=='withdrawn'?btn('Geri götür','withdraw',`data-id="${a.id}"`,'white'):''}</div>`).join(''):'<p class="subtle">Hələ müraciətin yoxdur. İmkanları kəşf etməyə başla.</p>'}</div><div class="section-head"><h2>Tədbirlərim</h2></div><div class="card">${m.registrations.length?m.registrations.map(r=>`<div class="row"><div><h3>${esc(r.title)}</h3><p>${statuses[r.status]}</p></div>${r.status==='registered'?btn('Biletim','ticket',`data-id="${r.item_id}"`,'light'):''}</div>`).join(''):'<p class="subtle">Tədbirə qoşulduqda biletin burada görünəcək.</p>'}</div><div class="section-head"><h2>Öyrənmə tarixçəm</h2></div><div class="card">${m.progress.map(p=>`<div class="row"><div><h3>${esc(p.title)}</h3><p>${JSON.parse(p.completed).length} dərs tamamlanıb</p></div><a class="btn light" href="#/item/${p.item_id}">Davam et</a></div>`).join('')||'<p class="subtle">Akademiyadan ilk kursunu seç.</p>'}</div><div class="section-head"><h2>Sənədlərim</h2></div><div class="card">${m.documents.map(d=>`<div class="row"><div><h3>${d.kind==='cv'?'CV':'Müsahibə məşqi'} · ${esc(d.body.name||d.body.role||'Sənəd')}</h3><p>${new Date(d.updated_at).toLocaleDateString('az-AZ')}</p></div>${btn('Aç',d.kind==='cv'?'cv':'interview',`data-id="${d.id}"`,'light')}</div>`).join('')||'<p class="subtle">CV və müsahibə məşqlərin burada saxlanacaq.</p>'}</div>${state.session.authMode==='password'?'<div class="actions">'+btn('Hesabdan çıx','logout','','white')+'</div>':'<div class="actions"><a class="btn white" href="/signout-with-chatgpt?return_to=/" target="_top">Hesabdan çıx</a></div>'}`}
function toolsPage(){return header('Bacarıqlarına güc qat.','Hər gün bir az daha hazır. Sənin üçün praktik inkişaf alətləri.')+`<div class="grid two">${[['compass','Arzu Kompası','Üç qısa cavab ver, bacarıqlarını seç və sənə uyğun peşə yollarını kəşf et.','pusula','Səyahətə başla'],['file-text','CV hazırlayıcı','Məlumatlarını doldur, hesabında saxla və Azərbaycan hərfləri ilə PDF yüklə.','cv','CV hazırla'],['mic','Müsahibə məşqi','STAR sualları ilə məşq et. Cavablarını saxla və yenidən nəzərdən keçir.','interview','Məşqə başla'],['graduation-cap','Ortalama hesablayıcı','Fənn krediti ilə çəkilən 100 ballıq akademik ortalamanı hesabla.','gpa','Hesabla'],['clock','Pomodoro','25 dəqiqə fokuslan, 5 dəqiqə fasilə ver. Kiçik addımlarla irəlilə.','pomodoro','Fokuslan']].map(([i,t,d,a,b])=>`<article class="card"><div class="course-cover">${ico(i)}<span>↗</span></div><h2>${t}</h2><p class="subtle">${d}</p>${btn(b+' '+ico('arrow-right'),a)}</article>`).join('')}</div>`}
function plans(){return header('İnkişafına uyğun plan.','Əsas imkanlar hər kəs üçün açıqdır. Aylıq planların nəzərdə tutulan xidmətləri:')+`<div class="notice warning">Hazırda pulsuz xidmətlər aktivdir. 3 ₼ və 5 ₼ planları ödəniş provayderi və AI xidməti qoşulduqdan sonra satışa açılacaq. İndi heç bir ödəniş tutulmur.</div><div class="grid">${[['Başlanğıc','0','Pulsuz, hər zaman',['Profil və imkanlara müraciət','Tədbir qeydiyyatı və icmaları izləmə','CV hazırlama və PDF yükləmə','Açıq kurslar və müsahibə sualları','GPA və Pomodoro alətləri']],['İrəli','3','Davamlı inkişaf üçün',['Başlanğıc planındakı hər şey','Ayda 3 AI müsahibə təhlili','Ayda 3 CV üzrə AI rəy','Şəxsi inkişaf planı','Tərəfdaş endirimləri — əlavə olunduqca']],['Üfüq','5','Daha çox məşq üçün',['İrəli planındakı hər şey','Ayda 8 AI müsahibə təhlili','Ayda 8 CV üzrə AI rəy','Müsahibə hazırlıq materialları','Qrup mentor sessiyalarına qeydiyyat']]].map(([t,p,d,features],n)=>`<article class="card plan ${n===1?'featured':''}"><span class="tag">${n===1?'TÖVSİYƏ EDİLƏN':n?'TEZLİKLƏ':'AKTİV'}</span><h2 style="margin-top:20px">${t}</h2><p>${d}</p><div class="price">${p} ₼ <small>/ ay</small></div><ul>${features.map(x=>'<li>✓ '+x+'</li>').join('')}</ul>${n?'<button class="btn light" disabled>Hələ satışda deyil</button>':'<a class="btn" href="#/profile">Pulsuz başla →</a>'}</article>`).join('')}</div><p class="subtle" style="margin-top:20px">Şirkətlə real müsahibə şirkətin seçimindən və mövcud proqramından asılıdır. Heç bir plan işə qəbul zəmanəti vermir. Fərdi mentor vaxtı aylıq 3–5 ₼ qiymətə daxil deyil.</p>`}
function managePage(){const m=state.manage,admin=state.session.user.role==='admin';return header(admin?'İdarəetmə paneli.':'Təşkilatın üçün məkan.',admin?'Məzmunu yoxla, müraciətləri idarə et və icmanı təhlükəsiz saxla.':'Təşkilat profili, imkan və tədbir yarat. Məzmun yayımdan əvvəl yoxlanılır.')+`<div class="actions" style="margin-bottom:25px">${btn('Təşkilat yarat','edit-content','data-kind="organization"')}${btn('İmkan əlavə et','edit-content','data-kind="opportunity"','light')}${btn('Tədbir əlavə et','edit-content','data-kind="event"','light')}</div><h2>Məzmunlar</h2><div class="card stack">${m.items.filter(x=>admin||x.kind!=='course').map(i=>`<div class="row"><div><h3>${esc(i.title)}</h3><span class="tag">${statuses[i.status]||i.status}</span></div><div class="actions">${i.kind!=='course'?btn('Redaktə','edit-content',`data-id="${i.id}"`,'white'):''}${admin&&i.status!=='published'?btn('Yayımla','moderate',`data-id="${i.id}" data-status="published"`,'light'):''}${admin&&i.status==='published'?btn('Arxivlə','moderate',`data-id="${i.id}" data-status="archived"`,'white'):''}</div></div>`).join('')||'<p class="subtle">İlk təşkilat profilini yarat.</p>'}</div><div class="section-head"><h2>Gələn müraciətlər</h2></div><div class="card">${m.applications.map(a=>`<div class="row"><div><h3>${esc(a.name)} · ${esc(a.title)}</h3><p>${esc(a.email)}</p><span class="tag">${statuses[a.status]}</span></div>${btn('Müraciətə bax','view-application',`data-id="${a.id}"`,'light')}</div>`).join('')||'<p class="subtle">Hələ müraciət daxil olmayıb.</p>'}</div><div class="section-head"><h2>Tədbir iştirakçıları</h2></div><div class="card">${m.registrations.map(r=>`<div class="row"><div><h3>${esc(r.name)}</h3><p>${esc(r.title)}</p></div><span class="tag">${statuses[r.status]}</span></div>`).join('')||'<p class="subtle">Qeydiyyatlar burada görünəcək.</p>'}</div>${admin?companyQueueHTML(m.companyQueue):''}${admin?`<div class="section-head"><h2>Yoxlama gözləyən rəylər</h2></div><div class="card">${m.reviews.map(r=>{const b=JSON.parse(r.body);return `<div class="row"><div><h3>${esc(state.items.find(x=>x.id===r.organization_id)?.title)} · ${b.rating}/5</h3><p>${esc(b.role)} — ${esc(b.text)}</p>${b.salary?'<p>'+b.salary+' ₼</p>':''}</div><div class="actions">${btn('Təsdiqlə','moderate',`data-id="${r.id}" data-type="review" data-status="approved"`,'light')}${btn('Rədd et','moderate',`data-id="${r.id}" data-type="review" data-status="rejected"`,'white')}</div></div>`}).join('')||'<p class="subtle">Yoxlama gözləyən rəy yoxdur.</p>'}</div>`:''}`}
async function render(){const token=++routeToken;const [path,query='']=(location.hash.slice(2)||'home').split('?'),[route,id]=path.split('/');if(state.pusula){state.pusula.destroy();state.pusula=null}if(route==='pusula')return openPusula(token);state.search=new URLSearchParams(query).get('q')||'';if(route==='opportunities')state.filter=new URLSearchParams(query).get('type')||'Hamısı';shell(route);$('#main').innerHTML='<div class="loading">Yüklənir…</div>';refreshIcons();try{if(['profile','saved','manage','company'].includes(route)&&!state.session.user){$('#main').innerHTML=header('Öz məkanına xoş gəlmisən.','Profilini yarat, imkanları saxla və inkişafını izləməyə başla.')+btn('Hesabına daxil ol','login');refreshIcons();return}let html;if(route==='home')html=home();else if(['opportunities','companies','campus','academy','events','reviews','saved','search'].includes(route))html=listing(route);else if(route==='item')html=await itemPage(id);else if(route==='profile'){state.me=await api('/me');state.session.user=state.me.user;html=profile()}else if(route==='manage'){state.manage=await api('/manage');html=managePage()}else if(route==='company')html=await (await loadCompany()).page(path);else if(route==='tools')html=toolsPage();else if(route==='plans')html=plans();else if(route==='privileges')html=header('Gənc olmağın üstünlükləri.','Təhsil, alətlər və icma fürsətləri.')+`<div class="grid two"><div class="card">${ico('book-open')}<h2 style="margin-top:15px">Pulsuz BURA Akademiya</h2><p class="subtle">Üç dərslik başlanğıc kursunu tamamla və sertifikatını al.</p><a class="btn" href="#/academy">Öyrənməyə başla</a></div><div class="card">${ico('gift')}<h2 style="margin-top:15px">Tərəfdaş təklifləri</h2><p class="subtle">Hazırda təsdiqlənmiş endirim yoxdur. Təşkilatlar təkliflərini paneldən paylaşa bilər.</p><a class="btn light" href="#/manage">Təşkilat profili yarat</a></div></div>`;else if(route==='privacy')html=header('Məxfilik və istifadə.','BURA-nın sınaq mərhələsində məlumatların necə işlənir.')+`<article class="card terms"><h3>Hesab və profil</h3><p>Hesab identifikatoru, ad və e-poçt, özün əlavə etdiyin profil məlumatları serverdə saxlanır. CV, müraciətlər, qeydiyyatlar və öyrənmə irəliləyişinə yalnız hesabınla daxil ola bilərsən.</p><h3>Müraciət və rəy</h3><p>Müraciət edəndə həmin andakı profil məlumatların və qeydin təşkilat sahibinə və platforma idarəçisinə görünür. Şirkət rəyləri yoxlanıldıqdan sonra adın göstərilmədən yayımlanır. Platforma rəyin hansı hesaba aid olduğunu saxlayır; tam anonimlik vədi verilmir. Rəyə başqa şəxslərin adını və əlaqə məlumatlarını yazma.</p><h3>AI və ödəniş</h3><p>AI düyməsi yalnız xidmət qoşulduqda açılır. AI təhlili seçiləndə cavabın təhlil provayderinə göndərilir. Ödəniş planları hazırda satışda deyil və kart məlumatı toplanmır.</p><h3>Sınaq məzmunu</h3><p>Nümunə elan və tədbirlər işarələnib. Kataloqda təşkilatın adı olması tərəfdaşlıq demək deyil. Platforma işə qəbul və ya rəsmi təhsil sənədi zəmanəti vermir.</p></article>`;else if(route==='about')html=header('Gəncsənsə, yerin buradır.','BURA — Azərbaycanın gəncləri üçün inkişaf və imkanlar məkanı.')+`<article class="card"><h2>Öz yolunu yarat.</h2><p>BURA öyrənməyi, icmaları, universitetləri, könüllülük və təcrübə imkanlarını bir araya gətirir. Burada CV hazırlaya, kurs keçə, tədbirə qoşula və təcrübəni paylaşa bilərsən.</p><p class="subtle">Platforma sınaq mərhələsindədir. Bütün karyera mərkəzlərini bir araya gətirmək məqsəddir; hələ tam kataloq deyil. Təşkilat nümayəndəsi öz profilini paneldən əlavə edə bilər.</p><a class="btn" href="#/manage">İcmanı BURA-ya gətir</a></article>`;else html=empty('Səhifə tapılmadı.','Menyudan başqa bölmə seç.');if(token!==routeToken)return;$('#main').innerHTML=html;refreshIcons()}catch(e){if(token===routeToken)$('#main').innerHTML=`<div class="error">${esc(e.message)}</div>${btn('Yenidən yoxla','reload')}`}}
function login(mode='login',opts={}){if(!state.session.user&&!opts.force&&!$('#modal').open&&!pusulaDone()){location.hash='#/pusula';return}state.afterLogin=opts.returnHash||null;if(state.session.authMode==='siwc'){window.open('/signin-with-chatgpt?return_to='+encodeURIComponent('/'+(opts.returnHash||location.hash)),'_top');return}modal(mode==='register'?'BURA-ya qoşul':'Yenidən xoş gəldin',`<p class="subtle">Öyrənməyə, kəşf etməyə və öz yolunu yaratmağa başla.</p><form data-form="auth" data-mode="${mode}">${mode==='register'?field('name','Ad və soyad','','text',true):''}${field('email','E-poçt','','email',true)}${field('password','Şifrə (ən az 10 simvol)','','password',true)}<p class="tiny">Davam etməklə <a class="textlink" href="#/privacy" data-action="close">məxfilik qaydaları</a> ilə tanış olduğunu bildirirsən.</p><button class="btn" type="submit">${mode==='register'?'Hesab yarat':'Daxil ol'}</button><div class="form-message" role="alert"></div></form><div class="actions">${btn(mode==='register'?'Hesabım var':'Yeni hesab yarat',mode==='register'?'login':'signup','','white')}</div>`)}
function requireUser(){if(state.session.user)return true;login();return false}
function cv(docId){if(!requireUser())return;const u=state.session.user,p=u.profile||{},d=state.me?.documents.find(x=>x.id===docId);const b=d?.body||{name:u.name,email:u.email,city:p.city,phone:p.phone,summary:p.bio,education:[p.university,p.specialty].filter(Boolean).join(' — '),experience:p.experience,skills:p.skills};modal('Sənin CV-n',`<p class="subtle">Məlumatları redaktə et. PDF-də yalnız buradakı məlumatlar görünəcək.</p><form data-form="cv" data-id="${d?.id||''}"><div class="field-grid">${field('name','Ad və soyad',b.name,'text',true)}${field('email','E-poçt',b.email,'email',true)}${field('phone','Telefon',b.phone)}${field('city','Şəhər',b.city)}${area('summary','Qısa profil',b.summary)}${area('education','Təhsil',b.education)}${area('experience','Təcrübə və layihələr',b.experience)}${area('skills','Bacarıqlar',b.skills)}</div><div class="actions"><button class="btn" type="submit" name="intent" value="save">Hesabımda saxla</button><button class="btn light" type="submit" name="intent" value="pdf">${ico('download')} PDF yüklə</button></div><div class="form-message" role="status"></div></form>`)}
function interview(docId){if(!requireUser())return;const d=state.me?.documents.find(x=>x.id===docId);modal('Müsahibə məşqi',`<div class="notice">${state.session.services.ai?'Cavabını AI ilə təhlil etdirə bilərsən. Mətnin AI provayderinə göndəriləcək.':'AI xidməti hələ qoşulmayıb. Aşağıdakı suallarla sərbəst məşq edə və cavablarını saxlaya bilərsən.'}</div><form data-form="interview" data-id="${d?.id||''}">${field('role','Hazırlaşdığın rol',d?.body.role||'Təcrübəçi','text',true)}<h3>Məşq sualları</h3><ol class="subtle"><li>Özün haqqında və bu sahəyə marağın barədə danış.</li><li>Komandada çətinlik yaşadığın bir vəziyyəti təsvir et. Konkret nə etdin?</li><li>Yeni bir bacarığı necə öyrəndin? Nəticəni necə ölçdün?</li></ol>${area('answers','Cavabların — situasiya, tapşırıq, addım, nəticə',d?.body.answers||'',true)}<div class="actions"><button class="btn" type="submit" name="intent" value="save">Məşqi saxla</button><button class="btn light" type="submit" name="intent" value="ai" ${!state.session.services.ai?'disabled':''}>AI ilə təhlil et</button></div><div class="form-message" role="status"></div><div id="feedback"></div></form>`)}
function editContent(id,kind){const i=state.manage.items.find(x=>x.id===id),b=i?.body||{};kind=i?.kind||kind;modal(i?'Məzmunu redaktə et':kind==='organization'?'Təşkilat profili yarat':kind==='event'?'Tədbir yarat':'İmkan yarat',`<form data-form="content" data-id="${id||''}" data-kind="${kind}">${field('title','Başlıq / ad',i?.title||'','text',true)}${kind!=='organization'?`<label>Təşkilat<select name="organization_id"><option value="">Şəxsi profilimdən</option>${state.manage.items.filter(x=>x.kind==='organization').map(x=>`<option value="${x.id}" ${i?.organization_id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>`:`<label>Növ<select name="type">${[['company','Şirkət'],['university','Universitet'],['career-center','Karyera mərkəzi'],['club','Tələbə klubu'],['school','Məktəb']].map(([v,t])=>`<option value="${v}" ${b.type===v?'selected':''}>${t}</option>`).join('')}</select></label>${field('sector','Sahə',b.sector||'Təhsil')}`}${area('description','Ətraflı məlumat (ən az 30 simvol)',b.description||'',true)}<div class="field-grid">${field('city','Şəhər',b.city||'Bakı')}${kind==='opportunity'?`<label>Kateqoriya<select name="category">${['İş','Təcrübə','Könüllülük','Freelance'].map(x=>`<option ${b.category===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('format','İş formatı',b.format||'Yerində')}${field('deadline','Son müraciət',b.deadline||'','date',true)}`:''}${kind==='event'?`${field('date','Tarix və saat (Bakı vaxtı)',b.date?.slice(0,16)||'','datetime-local',true)}${field('capacity','İştirakçı sayı',b.capacity||50,'number',true)}`:''}</div>${kind==='opportunity'?area('requirements','Tələblər',b.requirements||''):''}<button class="btn" type="submit">${state.session.user.role==='admin'?'Saxla və yayımla':'Yoxlamaya göndər'}</button><div class="form-message" role="status"></div></form>`)}
async function reloadData(){state.items=(await api('/catalog')).items;if(state.session.user)state.me=await api('/me')}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{if(a.startsWith('co-')){await (await loadCompany()).action(a,el);return}
 if(a==='page-reload'){location.reload();return}if(a==='close'){$('#modal').close();clearInterval(timerInterval);timerInterval=null;return}if(a==='menu'){const open=$('.mobile-nav').classList.toggle('open');el.setAttribute('aria-expanded',open);return}if(a==='login'||a==='signup'){login(a==='signup'?'register':'login');return}if(a==='reload'){await reloadData();render();return}if(a==='search'){location.hash='#/search';setTimeout(()=>$('#search')?.focus(),10);return}if(a==='filter'){location.hash='#/opportunities?type='+encodeURIComponent(el.dataset.filter);return}if(a==='cv'){cv(id);return}if(a==='pusula'){location.hash='#/pusula';return}if(a==='copy'){try{await navigator.clipboard.writeText(el.dataset.copy);toast('Kopyalandı.')}catch{toast('Kopyalanmadı.')}return}if(a==='focus-profile'){const f=$('#profile-form');f?.scrollIntoView({behavior:'smooth',block:'start'});f?.querySelector('input,textarea')?.focus({preventScroll:true});return}if(a==='interview'){interview(id);return}if(a==='edit-content'){editContent(id,el.dataset.kind);return}
 if(a==='pomodoro'){modal('Fokus vaxtı',`<p class="subtle">Bir tapşırıq seç və diqqətini ona yönəlt.</p><div class="chips"><button class="chip active" data-action="timer-mode" data-seconds="1500">25 dəq fokus</button><button class="chip" data-action="timer-mode" data-seconds="300">5 dəq fasilə</button></div><div class="timer" id="timer">25:00</div><div class="timer-actions">${btn('Başlat','timer-start')}${btn('Sıfırla','timer-reset','','white')}</div>`);timerSeconds=1500;timerEnd=0;return}
 if(a==='timer-mode'){clearInterval(timerInterval);timerInterval=null;timerSeconds=Number(el.dataset.seconds);timerEnd=0;document.querySelectorAll('[data-action="timer-mode"]').forEach(x=>x.classList.toggle('active',x===el));$('[data-action="timer-start"]').textContent='Başlat';updateTimer();return}if(a==='timer-reset'){clearInterval(timerInterval);timerInterval=null;timerSeconds=Number($('.chip.active[data-seconds]')?.dataset.seconds||1500);timerEnd=0;$('[data-action="timer-start"]').textContent='Başlat';updateTimer();return}if(a==='timer-start'){if(timerInterval){timerSeconds=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));clearInterval(timerInterval);timerInterval=null;el.textContent='Davam et'}else{timerEnd=Date.now()+timerSeconds*1000;el.textContent='Dayandır';timerInterval=setInterval(()=>{timerSeconds=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));updateTimer();if(!timerSeconds){clearInterval(timerInterval);timerInterval=null;el.textContent='Başlat';toast('Fokus tamamlandı. Fasilə vaxtıdır!')}},250)}return}
 if(a==='gpa'){modal('Kreditli orta bal',`<p class="subtle">Nəticə = cəmi (bal × kredit) / cəmi kredit. Universitetinin qaydaları fərqli ola bilər.</p><form data-form="gpa"><div id="gpa-rows">${gpaRow()}</div>${btn('Fənn əlavə et','gpa-add','','white')}<button class="btn" type="submit">Hesabla</button><div class="form-message" role="status"></div></form>`);return}if(a==='gpa-add'){$('#gpa-rows').insertAdjacentHTML('beforeend',gpaRow());refreshIcons();return}if(a==='gpa-delete'){if(document.querySelectorAll('.gpa-row').length>1)el.closest('.gpa-row').remove();return}
 if(!requireUser())return;
 if(a==='save'||a==='follow'){const r=await api('/items/'+id+'/'+a,'POST',{});await reloadData();toast(r.active?(a==='save'?'Hesabında saxlanıldı.':'İzləməyə başladın.'):'Siyahıdan çıxarıldı.');await render();return}
 if(a==='apply'){const qs=state.items.find(x=>x.id===id)?.body.questions||[];modal('Müraciət et',`<p class="subtle">Profilin${state.me?.compass?', Arzu Kompası nəticən':''}, cavabların və qeydin işəgötürənə görünəcək.</p><form data-form="apply" data-id="${id}">${qs.map(q=>`<fieldset class="co-apply-q"><legend>${esc(q.text)}</legend>${q.type==='text'?`<textarea name="q:${q.id}" maxlength="1000" required aria-label="${esc(q.text)}"></textarea>`:(q.type==='yesno'?[['yes','Bəli'],['no','Xeyr']]:q.options.map((o,k)=>[k,o])).map(([v,t])=>`<label class="choice"><input type="radio" name="q:${q.id}" value="${v}" required>${esc(t)}</label>`).join('')}</fieldset>`).join('')}${area('note','Niyə bu imkana qoşulmaq istəyirsən? (ən az 20 simvol)','',true)}<label class="choice"><input type="checkbox" name="consent" required>Profil məlumatlarımın və cavablarımın bu işəgötürənə göndərilməsinə razıyam.</label><button class="btn" type="submit">Müraciəti göndər</button><div class="form-message" role="alert"></div></form>`);return}
 if(a==='register-event'||a==='cancel-event'){await api('/items/'+id+'/register','POST',{cancel:a==='cancel-event'});await reloadData();await render();toast(a==='register-event'?'Qeydiyyatın saxlanıldı. Biletin hazırdır.':'Qeydiyyat ləğv edildi.');return}
 if(a==='ticket'){const r=state.me.registrations.find(x=>x.item_id===id&&x.status==='registered'),i=state.items.find(x=>x.id===id);if(!r)throw Error('Aktiv qeydiyyat tapılmadı.');modal('Tədbir biletin',`<span class="tag green">Qeydiyyat təsdiqləndi</span><h2 style="margin-top:20px">${esc(i?.title||r.title)}</h2><p>${esc(state.session.user.name)}</p><p>${i?new Date(i.body.date).toLocaleString('az-AZ',{timeZone:'Asia/Baku'}):''}</p><div class="notice">Bilet № <strong>${esc(r.id)}</strong></div>${i?.body.sample?'<p class="subtle">Sınaq bileti — real tədbir deyil.</p>':''}`);return}
 if(a==='review'){modal('Təcrübəni paylaş',`<div class="notice">Rəyin yoxlamadan sonra adın göstərilmədən yayımlanır. Platforma rəyin hesaba aidliyini saxlayır. Şəxsi adlar və məxfi məlumatlar yazma.</div><form data-form="review" data-id="${id}">${field('role','Vəzifən','','text',true)}<label>Qiymətləndirmə<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} / 5</option>`).join('')}</select></label>${field('salary','Aylıq xalis maaş, ₼ (istəyə bağlı)','','number')}${area('text','Təcrübən (ən az 30 simvol)','',true)}<button class="btn" type="submit">Yoxlamaya göndər</button><div class="form-message" role="alert"></div></form>`);return}
 if(a==='certificate'){const p=state.me.progress.find(x=>x.item_id===id&&x.certificate_id);if(!p)throw Error('Əvvəl bütün dərsləri tamamla.');await (await import('./pdf.js')).downloadPDF({...p,name:state.session.user.name},true);return}
 if(a==='notifications'){modal('Bildirişlərin',state.me.notifications.map(n=>`<div class="row"><div><h3>${esc(n.title)}</h3><a class="textlink" data-action="close" href="${esc(n.link)}">Bax →</a></div></div>`).join('')||'<p class="subtle">Hələ yeni bildiriş yoxdur.</p>');await api('/notifications','POST',{});return}
 if(a==='withdraw'){modal('Müraciəti geri götür',`<p>Bu elana yenidən müraciət edə bilməyəcəksən. Davam etmək istəyirsən?</p>${btn('Bəli, geri götür','withdraw-confirm',`data-id="${id}"`,'danger')}`);return}if(a==='withdraw-confirm'){await api('/application','POST',{id,status:'withdrawn'});$('#modal').close();await reloadData();render();return}
 if(a==='moderate'){await api('/moderate','POST',{id,type:el.dataset.type,status:el.dataset.status});await reloadData();await render();toast('Status yeniləndi.');return}
 if(a==='view-application'){const x=state.manage.applications.find(x=>x.id===id),p=JSON.parse(x.profile);modal('Müraciət',`<h2>${esc(x.name)}</h2><p>${esc(x.email)}</p><p class="subtle">${esc(x.note)}</p><h3>Müraciət anındakı profil</h3>${Object.entries(p.profile||{}).filter(([,v])=>v).map(([k,v])=>`<p class="subtle"><strong>${esc(({city:'Şəhər',university:'Universitet',specialty:'İxtisas',bio:'Haqqında',skills:'Bacarıqlar',experience:'Təcrübə',phone:'Telefon'})[k]||k)}:</strong> ${esc(v)}</p>`).join('')}${x.status!=='withdrawn'?`<form data-form="application" data-id="${id}"><label>Status<select name="status">${['reviewing','interview','accepted','rejected'].map(s=>`<option value="${s}" ${x.status===s?'selected':''}>${statuses[s]}</option>`).join('')}</select></label><button class="btn" type="submit">Statusu yenilə</button><div class="form-message" role="alert"></div></form>`:'<span class="tag">Geri götürülüb</span>'}`);return}
 if(a==='logout'){await api('/logout','POST',{});state.session=await api('/session');state.me=null;location.hash='#/home';await render();return}
 }catch(e){toast(e.message)}});
function gpaRow(){return `<div class="gpa-row"><input name="subject" placeholder="Fənn" aria-label="Fənnin adı"><input name="grade" placeholder="Bal" type="number" min="0" max="100" step="0.01" aria-label="Bal (0–100)" required><input name="credit" placeholder="Kredit" type="number" min="0.1" max="60" step="0.1" aria-label="Kredit" required><button type="button" class="iconbtn" data-action="gpa-delete" aria-label="Fənni sil">${ico('trash-2')}</button></div>`}
function updateTimer(){if($('#timer'))$('#timer').textContent=String(Math.floor(timerSeconds/60)).padStart(2,'0')+':'+String(timerSeconds%60).padStart(2,'0')}
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),type=f.dataset.form,message=f.querySelector('.form-message'),submit=e.submitter;if(f.id==='search-form'){location.hash='#/search?q='+encodeURIComponent(d.q);return}if(!type)return;if(message)message.textContent='';if(submit)submit.disabled=true;try{if(type.startsWith('co-')){await (await loadCompany()).submit(type,f,d,message);return}
 if(type==='auth'){const r=await api('/auth','POST',{...d,action:f.dataset.mode});state.session={...state.session,...r};await reloadData();let linked=false;try{linked=await saveCompass()}catch(e){toast(e.message)}$('#modal').close();if(location.hash.startsWith('#/pusula'))history.replaceState(null,'',state.afterLogin||'#/home');if(f.dataset.mode==='register'&&!linked&&!state.me?.compass&&onboardOnce())history.replaceState(null,'','#/pusula');else if(linked)onboardOnce();await render();toast('BURA-ya xoş gəldin!');return}
 if(type==='gpa'){const rows=[...f.querySelectorAll('.gpa-row')],weight=rows.reduce((s,r)=>s+Number(r.querySelector('[name=credit]').value),0),sum=rows.reduce((s,r)=>s+Number(r.querySelector('[name=grade]').value)*Number(r.querySelector('[name=credit]').value),0);message.innerHTML=`<div class="notice">Orta bal: <strong>${(sum/weight).toFixed(2)} / 100</strong> · ${weight} kredit</div>`;return}
 if(!requireUser())return;
 if(type==='profile'){await api('/profile','PUT',d);await reloadData();state.session.user=state.me.user;message.innerHTML='<div class="notice">Profil məlumatların saxlanıldı.</div>';return}
 if(type==='cv'||type==='interview'){
  const r=await api('/document','POST',{id:f.dataset.id||undefined,kind:type,body:d});f.dataset.id=r.id;await reloadData();message.innerHTML='<div class="notice">Hesabında saxlanıldı.</div>';
  if(type==='cv'&&submit?.value==='pdf')await(await import('./pdf.js')).downloadPDF(d);
  if(type==='interview'&&submit?.value==='ai'){const out=await api('/interview','POST',{role:d.role,answer:d.answers});$('#feedback').innerHTML=`<div class="notice" style="white-space:pre-line">${esc(out.feedback)}</div>`}return;
 }
 if(type==='lesson'){const r=await api('/items/'+f.dataset.id+'/learn','POST',{lesson:Number(f.dataset.lesson),answer:Number(d.answer)});if(!r.correct){message.innerHTML='<div class="notice warning">Bu cavab uyğun deyil. Dərsdəki nümunəyə yenidən bax və təkrar yoxla.</div>';return}await reloadData();await render();toast('Dərs tamamlandı!');return}
 if(type==='apply'){await api('/items/'+f.dataset.id+'/apply','POST',{note:d.note,consent:d.consent==='on',answers:Object.fromEntries(Object.entries(d).filter(([k])=>k.startsWith('q:')).map(([k,v])=>[k.slice(2),v]))});toast('Müraciətin göndərildi. Profilindən izləyə bilərsən.')}
 if(type==='review'){await api('/items/'+f.dataset.id+'/review','POST',d);toast('Rəyin yoxlamaya göndərildi.')}
 if(type==='application'){await api('/application','POST',{id:f.dataset.id,...d});toast('Status yeniləndi və istifadəçiyə bildiriş yaradıldı.')}
 if(type==='content'){if(f.dataset.kind==='event')d.date=d.date+':00+04:00';await api('/content','POST',{...d,id:f.dataset.id||undefined,kind:f.dataset.kind});toast('Məzmun saxlanıldı.')}
 $('#modal').close();await reloadData();await render();
 }catch(err){if(message)message.innerHTML=`<div class="error">${esc(err.message)}</div>`;else toast(err.message)}finally{if(submit)submit.disabled=false}});
$('#modal').addEventListener('close',()=>{clearInterval(timerInterval);timerInterval=null});
document.addEventListener('change',async e=>{const box=e.target.closest('[data-plan]');if(!box)return;box.disabled=true;try{const r=await api('/compass/plan','POST',{index:Number(box.dataset.plan),done:box.checked});if(state.me)state.me.compass={...state.me.compass,...r.compass};const plan=r.compass.kit.plan,n=plan.filter(x=>x.done).length,card=box.closest('.me-plan');card.querySelector('[data-plan-count]').textContent=n+'/'+plan.length;card.querySelector('[data-plan-bar]').style.width=(plan.length?n/plan.length*100:0)+'%';if(n===plan.length)toast('4 həftəlik planı tamamladın!')}catch(err){box.checked=!box.checked;toast(err.message)}finally{box.disabled=false}});
document.addEventListener('input',e=>{if(e.target.dataset?.coFilter&&companyModule)companyModule.input(e)});
document.addEventListener('change',e=>{if(!companyModule)return;if(e.target.dataset?.coFilter||e.target.dataset?.coSelect)companyModule.input(e);else if(e.target.closest('[data-co-change]'))companyModule.change(e)});
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();window.scrollTo({top:0});render()});
async function boot(){try{state.session=await api('/session');await reloadData();if(state.session.user){const linked=await saveCompass().catch(()=>false);if(!linked&&!state.me?.compass&&['','#','#/','#/home'].includes(location.hash)&&onboardOnce())history.replaceState(null,'','#/pusula')}else if(!pusulaDone()&&['','#','#/','#/home'].includes(location.hash))history.replaceState(null,'','#/pusula');await render()}catch(e){shell('home');$('#main').innerHTML=header('BURA','Gəncliyin yeni məkanı')+`<div class="error">${esc(e.message)}</div><button class="btn" data-action="page-reload">Yenidən yoxla</button>`;refreshIcons()}}boot();
